import{_ as i,C as t,o as l,c as h,a2 as a,j as o,G as n}from"./chunks/framework.BgSoyxN5.js";const f=JSON.parse('{"title":"U.S. Economic Health: The Whole Macro Picture, Monthly | TickerForge","description":"Twenty-plus macro indicators as one composite with four bands, published monthly with the indicators holding it up and dragging it down named on both sides. What it answers and how to publish it.","frontmatter":{"title":"U.S. Economic Health: The Whole Macro Picture, Monthly | TickerForge","description":"Twenty-plus macro indicators as one composite with four bands, published monthly with the indicators holding it up and dragging it down named on both sides. What it answers and how to publish it.","aside":false,"locale":"en","alternateLocales":{"en":"/market-intelligence/economic-health","ru":"/ru/market-intelligence/economic-health"},"pageClass":"partners-page"},"headers":[],"relativePath":"market-intelligence/economic-health.md","filePath":"market-intelligence/economic-health.md","lastUpdated":1788182993000}'),c={name:"market-intelligence/economic-health.md"},d={class:"partners-wide"},m={class:"partners-post-gallery"};function p(u,e,g,w,b,k){const r=t("PartnerPostImage"),s=t("PartnerChannelCta");return l(),h("div",null,[e[0]||(e[0]=a('<h1 id="u-s-economic-health" tabindex="-1">U.S. Economic Health <a class="header-anchor" href="#u-s-economic-health" aria-label="Permalink to &quot;U.S. Economic Health&quot;">​</a></h1><p>Macro news arrives one indicator at a time — CPI day, payrolls day, ISM day. Nobody publishes the sum. This does, once a month.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="https://t.me/TickerForgeBot?start=src_channel_us_economy" rel="nofollow">Open the US Economy menu</a><a class="partners-button partners-button--secondary" href="#publish">Publish it in your channel</a></div><p class="partners-locale-switch"><a href="/ru/market-intelligence/economic-health" hreflang="ru">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/market-intelligence/">All market intelligence reads</a> · <a href="/market-intelligence/market-regime">Market Regime</a> · <a href="/market-intelligence/market-stress">Market Stress</a></p><h2 id="answers" tabindex="-1">The Question It Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;The Question It Answers {#answers}&quot;">​</a></h2><p><strong>&quot;Is the macro backdrop supporting risk-taking, or working against it?&quot;</strong></p><p>A single print cannot answer that. Payrolls beat and CPI missed in the same month happens constantly, and a feed covering both leaves a reader with two facts and no position. The composite exists because the answer lives in the aggregate, not in the latest release.</p><h2 id="why" tabindex="-1">Why A Composite Beats A Release Calendar <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why A Composite Beats A Release Calendar {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Twenty-plus indicators, one score.</strong> Each is scored against its own historical norm, so &quot;good&quot; means good relative to that series&#39; own history rather than against a round number.</li><li><strong>Four bands, not a bare number.</strong> Recession risk, Slowing, Stable growth, Expansion. A score of 61 means nothing on its own; the band it falls in does.</li><li><strong>The drivers are named on both sides.</strong> Every post lists what is holding the score up and what is dragging it down. That is the part a reader can argue with, and the part that makes the number more than a verdict.</li><li><strong>Preliminary is labelled preliminary.</strong> Late data changes the score, and the post says how much of the month has reported rather than presenting an incomplete read as final.</li><li><strong>The last three months come with it.</strong> One macro number is trivia. The direction of three is a story.</li></ul></div><h2 id="example" tabindex="-1">What The Post Looks Like <a class="header-anchor" href="#example" aria-label="Permalink to &quot;What The Post Looks Like {#example}&quot;">​</a></h2>',11)),o("div",d,[o("div",m,[n(r,{src:"/partners/examples/economic-health-sample.png",alt:"TickerForge U.S. Economic Health post: monthly macro composite with band, drivers on both sides and the last three months",caption:"The score, its band, what moved it, and the trend behind it."})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">How It Is Built <a class="header-anchor" href="#method" aria-label="Permalink to &quot;How It Is Built {#method}&quot;">​</a></h2><p>Each indicator is turned into a z-score against its own history, signed so that &quot;up&quot; always means &quot;better for the economy&quot; — including for series like unemployment where a higher published value is the bad one — then age-decayed, weighted and scaled into a 0–100 composite.</p><p>Full write-up: <a href="/blog/economic-health-score">How we score the economy</a>.</p><h2 id="publish" tabindex="-1">Two Ways To Use It <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Two Ways To Use It {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Read it.</strong> The monthly post runs on the TickerForge public channel; all 20+ indicators, the score chart and monthly alerts live in the bot&#39;s US Economy menu.</li><li><strong>Publish it.</strong> An approved partner generates the same post with their own tracked link inside it, in English or Russian, in one tap. See <a href="/partners/market-news">Market News partners</a>.</li></ul></div>',5)),n(s),e[2]||(e[2]=a('<p>A macro composite is context, not a signal. A supportive backdrop is not a reason to add risk and a weak one is not a reason to sell. TickerForge is educational decision-support software, not financial advice.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/market-intelligence/">All market intelligence reads</a></li><li><a href="/blog/economic-health-score">How we score the economy</a></li><li><a href="/market-intelligence/market-regime">Market Regime</a></li><li><a href="/partners/market-news">Market news partner program</a></li></ul>',3))])}const T=i(c,[["render",p]]);export{f as __pageData,T as default};
